const {open}=require('node:fs/promises');
module.exports=async function(file){
  const h=await open(file);const rl=h.readLines({highWaterMark:1});
  const closed=new Promise(resolve=>rl.input.once('close',resolve));
  const rows=[];try{for await(const line of rl)rows.push(JSON.parse(line));}
  finally{rl.close();rl.input.destroy();await closed;await h.close();}
  return {rows,closed:h.fd===-1};
};

